def track_drifters(width, height, coast, field, drifters):
    'Given the original dimensions, coast and drifter rows and a fixed public field list, return the original {id, path, blocked_steps} rows sorted by ID. A path includes the start and an entry after each step. Off-grid and coast proposals stay in place and count as blocked, while a legal zero displacement does not. Preserve inputs.\n\nLocal check: Supply a fixed 2 by 2 field row with vector (1,0) at (0,0), and coast (1,0). A drifter starting at (0,0) for 2 steps returns three copies of [0,0] and blocked_steps 2. On a separate fixed zero-vector start, one step stays put with blocked_steps 0.'
    raise NotImplementedError

def fit_field(width, height, coast, samples):
    'Return the public field list sorted by (y, x), with one {x, y, dx, dy, error, gap} row for each sea cell. coast and samples retain their public shapes. Use the published displacement, weighted-error, tie, second distinct vector and no-observation rules. Preserve inputs.\n\nLocal check: On a 2 by 2 grid with one coast cell, give cell (0,0) equal-weight observations (-1,0) and (1,0). Its fitted row has (dx,dy)=(-1,0), error 2 and gap 0. The coast has no row and unobserved sea cells have zero vector, error and gap.'
    raise NotImplementedError

"""Comparison for JSON reports: keyed collections and equivalent fractions."""
from fractions import Fraction
import json

UNORDERED = {
    'Q01': {'models', 'events', 'retained', 'excluded'},
    'Q02': {'results'},
    'Q03': set(),
    'Q04': {'runs'},
    'Q05': {'queries', 'coefficients', 'min_assignment', 'max_assignment'},
    'Q06': {'levels','segments','components','vertices','endpoints'},
    'Q07': {'accounts'},
    'Q08': set(),
    'Q09': {'queries','blockers','components'},
    'Q10': {'precincts','discrepancies'},
    'Q11': {'lots','bids','reasons','allocations'},
    'Q12': {'queries','claim_dependencies','publications','cited_versions','stale_versions','retracted_publications'},
    'Q13': {'queries','affected_assemblies','impacted_shipments','open_shipments','suppliers','retailers'},
    'Q14': {'jobs','cycles','members','waits_on'},
    'Q15': {'events','comparisons','causal_violations'},
    'Q16': set(),
    'Q17': {'nodes','members'},
    'Q18': {'crowns'},
    'Q19': {'nights','targets','light_curve','used_references','rejected_references'},
    'Q20': {'field','tracks'},
}

def normalize(task, value, field=''):
    if isinstance(value, dict):
        if set(value) == {'num', 'den'} and type(value['num']) is int and type(value['den']) is int and value['den']:
            fraction = Fraction(value['num'], value['den'])
            return {'num':fraction.numerator, 'den':fraction.denominator}
        return {k: normalize(task, v, k) for k, v in value.items()}
    if isinstance(value, list):
        if task == 'Q19' and field in {'zero_point','calibrated','residual','baseline'} and len(value)==2 and all(type(x) is int for x in value) and value[1]:
            fraction = Fraction(*value)
            return [fraction.numerator, fraction.denominator]
        items = [normalize(task, v) for v in value]
        if field in UNORDERED[task]:
            return sorted(items, key=lambda v: json.dumps(v, sort_keys=True))
        return items
    return value

def check_value(ident, name, actual, wanted, context=None):
    try:
        return json.dumps(normalize(ident, actual), sort_keys=True) == json.dumps(normalize(ident, wanted), sort_keys=True)
    except (TypeError, ValueError, OverflowError):
        return False

