from engines.analysis.field_fit import fit_field
from engines.analysis.drifter_tracking import track_drifters
from runtime import build, read


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]
    field = fit_field(
        request["width"],
        request["height"],
        request["coast"],
        request["samples"],
    )
    tracks = track_drifters(
        request["width"],
        request["height"],
        request["coast"],
        field,
        request["drifters"],
    )
    return {"field": field, "tracks": tracks}


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

import unittest

visible_document = "engines/analysis/SPEC.md"

API_BOUNDARY_REQUIREMENTS = [
    {
        "target_path": "engines/analysis/engine.py",
        "function": "transform",
        "rules": {
            "nonfinite_unknown_field": {
                "applicable": False,
                "contract_path": visible_document,
                "requirement_quote": (
                    "Input: width and height 2\u20135, `coast` unique `[x,y]` "
                    "blocked cells."
                ),
                "reason": (
                    "SPEC.md defines only valid domain inputs and the report "
                    "output; it never requires transform to reject non-finite "
                    "values or unknown fields with a ValueError."
                ),
            },
            "invalid_payload_type": {
                "applicable": False,
                "contract_path": visible_document,
                "requirement_quote": (
                    "Return the complete JSON-compatible report and leave "
                    "caller inputs intact."
                ),
                "reason": (
                    "The prompt states the evaluator calls transform(payload, "
                    "contract), but no visible document requires ValueError "
                    "for a scalar or otherwise malformed payload type."
                ),
            },
        },
    },
]


class AnalysisTransformBehaviorTests(unittest.TestCase):
    """Independent behavior probes derived from SPEC.md."""

    def test_field_lexicographic_tie_gap_zero_and_unobserved_zero(self):
        # Two equal-weight observations with the same minimum error: SPEC.md
        # requires the lexicographically smallest (dx, dy), and gap may be 0
        # on a tie.  Unobserved sea cells must be forced to (0,0), error 0,
        # gap 0.  The public fixture does not exercise a tie.
        payload = {
            "request": {
                "width": 2,
                "height": 2,
                "coast": [[1, 1]],
                "samples": [
                    {"x": 0, "y": 0, "dx": -1, "dy": 0, "weight": 1},
                    {"x": 0, "y": 0, "dx": 1, "dy": 0, "weight": 1},
                ],
                "drifters": [
                    {"id": "D", "start": [1, 0], "steps": 1},
                ],
            }
        }
        result = call_candidate(
            "engines/analysis/engine.py",
            "transform",
            args=[payload, {"task": "Q20"}],
        )
        self.assertEqual(
            result["field"],
            [
                {"x": 0, "y": 0, "dx": -1, "dy": 0, "error": 2, "gap": 0},
                {"x": 1, "y": 0, "dx": 0, "dy": 0, "error": 0, "gap": 0},
                {"x": 0, "y": 1, "dx": 0, "dy": 0, "error": 0, "gap": 0},
            ],
        )
        self.assertEqual(
            result["tracks"],
            [
                {
                    "id": "D",
                    "path": [[1, 0], [1, 0]],
                    "blocked_steps": 0,
                },
            ],
        )

    def test_tracker_off_grid_blocked_and_zero_displacement(self):
        # Off-grid proposals must stay in place and count as blocked, while a
        # legal zero displacement stays without a blocked step.  Tracks are
        # sorted by ID.  The public fixture covers coast blocking but not
        # off-grid or zero-vector moves.
        payload = {
            "request": {
                "width": 2,
                "height": 2,
                "coast": [[1, 1]],
                "samples": [
                    {"x": 0, "y": 1, "dx": -1, "dy": 0, "weight": 1},
                ],
                "drifters": [
                    {"id": "Z", "start": [0, 0], "steps": 2},
                    {"id": "A", "start": [0, 1], "steps": 2},
                ],
            }
        }
        result = call_candidate(
            "engines/analysis/engine.py",
            "transform",
            args=[payload, {"task": "Q20"}],
        )
        tracks = result["tracks"]
        self.assertEqual([row["id"] for row in tracks], ["A", "Z"])
        self.assertEqual(
            tracks[0],
            {
                "id": "A",
                "path": [[0, 1], [0, 1], [0, 1]],
                "blocked_steps": 2,
            },
        )
        self.assertEqual(
            tracks[1],
            {
                "id": "Z",
                "path": [[0, 0], [0, 0], [0, 0]],
                "blocked_steps": 0,
            },
        )


if __name__ == "__main__":
    unittest.main()

